// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsConfigPath 是仓库根下的按仓库阈值配置。
const thresholdsConfigPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 它从 config/thresholds.json 里读该仓库的阈值；文件不存在、读不出来、
// 内容不是 JSON 对象、或该仓库没配置时，回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := readThresholds(thresholdsPath())
	if err != nil {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// thresholdsPath 在仓库里定位 config/thresholds.json。
//
// 测试进程的工作目录是包目录（inventory/），所以从当前目录逐级向上找；
// 找不到时返回仓库相对路径，交给 ReadFile 报错后回退。
func thresholdsPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return thresholdsConfigPath
	}
	for {
		candidate := filepath.Join(dir, thresholdsConfigPath)
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return thresholdsConfigPath
		}
		dir = parent
	}
}

// readThresholds 解析配置文件。顶层必须是 JSON 对象（仓库名 -> 阈值）。
func readThresholds(path string) (map[string]int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, err
	}
	if thresholds == nil {
		return nil, errors.New("thresholds: 顶层不是 JSON 对象")
	}
	return thresholds, nil
}
```

